={{ (() => {
  const cfg = $('Load Config').first().json.config;
  const t = cfg.messageTemplates;
  const intent = $('Validate Intent').first().json.intent;
  try { const av = $('Compute Availability').first().json; if (av && av.computed_reply) return av.computed_reply; } catch (e) {}
  if (intent === 'confirm') { for (const n of ['Build Booked State','Build Mirror-Failed State','Build Race-Lost State','Build Orphan State','Build Verify-Unavailable State']) { try { const r = $(n).first().json; if (r && r.computed_reply) return r.computed_reply; } catch (e) {} } }
  if (intent === 'answer_faq')    return $('Answer FAQ').first().json.computed_reply;
  if (intent === 'capture_lead')  return $('Build Lead State').first().json.computed_reply;
  const f = $json.fields;
  const st = $('Merge State').first().json.state; // last_updated_prev = PRE-write snapshot (Merge runs before Save) → compares to the previous turn, not this one
  let newSession = true;
  if (st.last_updated_prev) {
    const prev = DateTime.fromISO(st.last_updated_prev, { zone: 'utc' });
    newSession = DateTime.utc().diff(prev, 'minutes').minutes > cfg.bot.sessionGapMinutes;
  }
  const greet = (st.found && newSession) ? 'Welcome back! ' : '';
  if (f.stage === 'handoff')      return t.handoff;
  // defensive fallback — the book flow now routes ready -> availability -> confirming, so this rarely fires
  if (f.stage === 'ready')        return greet + 'Great — ' + f.slot_service + ' on ' + f.slot_date + ' at ' + f.slot_time + '. (demo — booking confirmation is Phase 3)';
  if (f.stage === 'collecting')   return greet + (f.slot_service ? t.askDateTime : t.askService);
  return greet + '[demo] classified as ' + intent;
})() }}

