let answer;
switch (topic) {
  case 'price': {
    const one = serviceId ? svc.find(s => s.id === serviceId) : null;
    answer = one
      ? `${one.name} is ${money(one)}.`
      : 'Our prices: ' + svc.map(s => `${s.name} ${money(s)}`).join(', ') + '.';
    break;
  }
  case 'services':
    answer = 'We offer: ' + svc.map(s => `${s.name} (${s.durationMin} min)`).join(', ') + '.';
    break;
  case 'hours': {
    const days = ['mon','tue','wed','thu','fri','sat','sun'];
    const label = { mon:'Mon', tue:'Tue', wed:'Wed', thu:'Thu', fri:'Fri', sat:'Sat', sun:'Sun' };
    const wh = cfg.workingHours || {};
    answer = 'Opening hours — ' + days
      .map(d => `${label[d]}: ${(wh[d] && wh[d].length) ? wh[d].join(', ') : 'closed'}`)
      .join(' · ') + '.';
    break;
  }
  case 'address':
  case 'parking':
  case 'walkin':
    answer = (cfg.faq && cfg.faq[topic]) || cfg.messageTemplates.faqUnknown;
    break;
  default:  // 'other', null veya beklenmedik → dürüst deflect, ASLA tahmin
    answer = cfg.messageTemplates.faqUnknown;
}

return [{ json: { ...$json, computed_reply: answer } }];

// Build Lead State — Airtable create SONRASI: state'i (Validate Intent'ten) yeniden bağla + computed_reply=leadCaptured.
// computed_reply Airtable'a YAZILMAZ; item'da taşınır, Build Reply guard'lı referansla okur.
const vi  = $('Validate Intent').first().json;   // channel, sender_key, intent='capture_lead', state{stage,slots,turn_count,last_intent}
const cfg = $('Load Config').first().json.config;
return [{ json: {
  channel: vi.channel,
  sender_key: vi.sender_key,
  intent: vi.intent,                 // 'capture_lead' → Build Reply guard'ı için
  state: vi.state,                   // stage/slots/turn_count/last_intent='capture_lead' → Save State bunu yazar
  computed_reply: cfg.messageTemplates.leadCaptured
} }];

// Build FreeBusy Query — the requested day's UTC window (shop-tz aware, DST-correct) for freeBusy.
const cfg = $('Load Config').first().json.config;
const tz = cfg.business.timezone;
const date = $json.state.slots.date;
const dayStart = DateTime.fromISO(date, { zone: tz }).startOf('day').toUTC().toISO();
const dayEnd = DateTime.fromISO(date, { zone: tz }).endOf('day').toUTC().toISO();
return [{ json: { ...$json, freebusy: { timeMin: dayStart, timeMax: dayEnd, calId: cfg.googleCalendarId } } }];

// Compute Availability — working hours (shop tz) minus GCal busy; does the slot fit? + alternatives. UTC/DST-correct.
const cfg = $('Load Config').first().json.config;
const gate = $('Slot Gate').first().json;
const st = gate.state;
const tz = cfg.business.timezone;
const slots = st.slots;
const svc = (cfg.services || []).find(s => s.id === slots.serviceId);
const dur = svc ? svc.durationMin : 30;
const svcName = svc ? svc.name : (slots.serviceId || 'your service');
const start = DateTime.fromISO(slots.date + 'T' + slots.time, { zone: tz });
const end = start.plus({ minutes: dur });
const now = DateTime.now().setZone(tz);
const wdKey = ['mon','tue','wed','thu','fri','sat','sun'][start.weekday - 1];
const windows = (cfg.workingHours && cfg.workingHours[wdKey]) || [];
const wins = windows.map(w => { const p = w.split('-'); return { open: DateTime.fromISO(slots.date + 'T' + p[0], { zone: tz }), close: DateTime.fromISO(slots.date + 'T' + p[1], { zone: tz }) }; });
const cals = $json.calendars || {};
const firstCal = Object.values(cals)[0] || { busy: [] };
if (firstCal.errors && firstCal.errors.length) throw new Error('calendar_error: ' + JSON.stringify(firstCal.errors)); // fail-loud: freeBusy 200 with errors is NOT 'available'
const busy = (firstCal.busy || []).map(b => ({ s: DateTime.fromISO(b.start), e: DateTime.fromISO(b.end) }));
const overlaps = (s, e) => busy.some(b => s < b.e && b.s < e);
const withinHours = (s, e) => wins.some(w => s >= w.open && e <= w.close);
const fmt = start.toFormat('cccc d LLL HH:mm');
let stage, reply, status;
if (!slots.date || !slots.time || !start.isValid) { status = 'invalid'; stage = 'collecting'; reply = `Sorry, I couldn't read that date/time — what day and time would you like?`; }
else if (start < now) { status = 'past'; stage = 'collecting'; reply = `${fmt} has already passed — give me a future day and time.`; }
else if (wins.length === 0 || !withinHours(start, end)) { status = 'closed'; stage = 'collecting'; const hrs = windows.length ? windows.join(', ') : 'closed that day'; reply = `We're closed then — on ${start.toFormat('cccc')} we're open ${hrs}. What time works?`; }
else if (overlaps(start, end)) { status = 'busy'; stage = 'collecting'; const alts = []; for (const w of wins) { let t = w.open; while (t.plus({ minutes: dur }) <= w.close && alts.length < 3) { const te = t.plus({ minutes: dur }); if (t >= now && !overlaps(t, te)) alts.push(t.toFormat('HH:mm')); t = t.plus({ minutes: 30 }); } } reply = alts.length ? `${fmt} is taken. Free that day: ${alts.join(', ')}. Which works?` : `${fmt} is taken and that day is full — want another day?`; }
else { status = 'available'; stage = 'confirming'; reply = `${svcName}, ${fmt} — shall I book it? (yes / no)`; }
return [{ json: { ...gate, state: { ...st, stage }, availability: { status }, computed_reply: reply } }];

// Build Event Request — GCal events.insert payload from confirmed slots (shop tz + UTC, DST-correct, NO attendees).
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const slots = st.slots;
const tz = cfg.business.timezone;
const svc = (cfg.services || []).find(s => s.id === slots.serviceId);
const dur = svc ? svc.durationMin : 30;
const svcName = svc ? svc.name : slots.serviceId;
const name = (vi.slots && vi.slots.customerName) || null;
const start = DateTime.fromISO(slots.date + 'T' + slots.time, { zone: tz });
const end = start.plus({ minutes: dur });
const summary = svcName + (name ? ' — ' + name : '') + ' (bot)';
// CP2c-ii: deterministic GCal event id from the BOOKING KEY (sender_key|date|time|service), hex-encoded
// (valid base32hex, injective → no collisions). Same booking key → same id → a duplicate insert 409s, so a
// retry (or an insert whose response was lost) reconciles to the existing event instead of double-booking.
const bkey = [vi.sender_key, slots.date, slots.time, slots.serviceId].join('|');
const eventId = Array.from(bkey).map(c => c.charCodeAt(0).toString(16).padStart(2, '0')).join('');
return [{ json: { ...vi, booking: { calId: cfg.googleCalendarId, timeZone: tz, startISO: start.toISO(), endISO: end.toISO(), startUTC: start.toUTC().toISO(), endUTC: end.toUTC().toISO(), summary, service: slots.serviceId, serviceName: svcName, customerName: name, dateStr: start.toFormat('cccc d LLL'), timeStr: start.toFormat('HH:mm'), eventId } } }];

// Build Booked State — GCal write OK (event id) -> booked + confirmation. gcal_event_id carried (mirror + cancel).
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const b = be.booking;
const st = be.state;
const eventId = $('Build Event Request').first().json.booking.eventId || null;
const t = cfg.messageTemplates;
const reply = (t.bookingConfirmed || `You're booked: {service}, {date} {time}. See you then!`).split('{service}').join(b.serviceName).split('{date}').join(b.dateStr).split('{time}').join(b.timeStr);
return [{ json: { ...be, state: { ...st, stage: 'booked' }, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Check Race — write-then-verify (booking-integrity): after our GCal insert, re-read the slot window.
// Any OTHER event overlapping our slot means we lost the concurrency race and must yield OUR event.
// events.list returns the RAW list (unlike freeBusy) — exclude cancelled + transparent ("Free") events.
const cfg = $('Load Config').first().json.config;
const tz = cfg.business.timezone;
const be = $('Build Event Request').first().json;
const b = be.booking;
const ourId = $('Build Event Request').first().json.booking.eventId;
const ourStart = new Date(b.startUTC).getTime();
const ourEnd = new Date(b.endUTC).getTime();
// Codex #3+#4: the verify read is INCOMPLETE if it was paginated (nextPageToken) OR the calendar's own
// timezone differs from the shop tz (all-day boundary math would be wrong). Fail safe: yield our event +
// mark verify_incomplete so the customer gets a NEUTRAL "couldn't confirm" message (never "just taken"),
// and never enter the happy path on an uncertain read.
const calTz = $json.timeZone;
if ($json.nextPageToken || (calTz && calTz !== tz)) {
  return [{ json: { ...be, gcal_event_id: ourId, race_lost: true, race_other_count: -1, verify_incomplete: true } }];
}
// Codex #5: all-day events carry start.date (no time) — parse at shop-tz midnight, NOT UTC midnight.
const toMs = (p) => {
  if (!p) return null;
  if (p.dateTime) return new Date(p.dateTime).getTime();
  if (p.date) return DateTime.fromISO(p.date, { zone: tz }).toMillis();
  return null;
};
const items = $json.items || [];
const overlaps = items.filter(ev => {
  if (ev.status === 'cancelled') return false;
  if (ev.transparency === 'transparent') return false;
  const s = toMs(ev.start);
  const e = toMs(ev.end);
  if (s === null || e === null) return false;
  return s < ourEnd && e > ourStart;
});
const others = overlaps.filter(ev => ev.id !== ourId);
return [{ json: { ...be, gcal_event_id: ourId, race_lost: others.length >= 1, race_other_count: others.length } }];

// Build Race-Lost State — lost the race AND successfully deleted OUR event (clean withdrawal).
// Slot yielded to the other booking; customer handed to a human. No orphan (our event is gone).
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const st = be.state;
const vi = (() => { try { return $('Check Race').first().json.verify_incomplete === true; } catch (e) { return false; } })();
const reply = vi ? (cfg.messageTemplates.verifyIncomplete || 'We could not finish confirming that time just now — a team member will follow up to lock it in.') : ((cfg.messageTemplates.slotJustTaken) || 'Sorry — that time was just taken. A team member will help you find another slot.');
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, race_lost: true, gcal_event_id: null, computed_reply: reply, _post_write: true } }];

// Build Orphan State — lost the race but the DELETE of our event FAILED → our event is still on the calendar.
// Visible, recoverable double-book: persist gcal_event_id so the owner can delete the stray event by hand.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const st = be.state;
const ourId = $('Build Event Request').first().json.booking.eventId;
const vi = (() => { try { return $('Check Race').first().json.verify_incomplete === true; } catch (e) { return false; } })();
const reply = vi ? (cfg.messageTemplates.verifyIncomplete || 'We could not finish confirming that time just now — a team member will follow up to lock it in.') : ((cfg.messageTemplates.slotJustTaken) || 'Sorry — that time was just taken. A team member will help you find another slot.');
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, orphan_event: true, gcal_event_id: ourId, computed_reply: reply, _post_write: true } }];

// Build Verify-Unavailable State — the post-write verify READ failed (calendar unreachable).
// The event IS written. We do NOT delete on a read-failure (could cancel a legit sole booking) and we do
// NOT return 503 (a provider retry would double-book). Keep the event, hand off, flag distinctly for the owner.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const st = be.state;
const ourId = $('Build Event Request').first().json.booking.eventId;
const reply = (cfg.messageTemplates.bookingNeedsConfirm) || "Thanks! We're confirming your booking now — a team member will follow up shortly.";
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, verify_unavailable: true, gcal_event_id: ourId, computed_reply: reply, _post_write: true } }];

// Build Mirror-Failed State — GCal event is written (authoritative) but the Airtable appointments MIRROR failed.
// The booking IS real, so we still confirm to the customer; but flag mirror_failed + keep gcal_event_id so the
// owner (Phase-5 alert) can repair the missing mirror row. Fail-loud on the mirror, never silent.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const b = be.booking;
const st = be.state;
const eventId = $('Build Event Request').first().json.booking.eventId || null;
const t = cfg.messageTemplates;
const reply = (t.bookingConfirmed || `You're booked: {service}, {date} {time}. See you then!`).split('{service}').join(b.serviceName).split('{date}').join(b.dateStr).split('{time}').join(b.timeStr);
return [{ json: { ...be, state: { ...st, stage: 'booked' }, mirror_failed: true, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Dedupe Gate — Airtable search REPLACES the item, so re-attach the normalized payload from Normalize Inbound.
// Empty search (alwaysOutputData) yields no record id → not a duplicate; a returned record id → already processed.
const norm = $('Normalize Inbound').first().json;
const hit = !!($json && $json.id);
return [{ json: { ...norm, _duplicate: hit } }];

// Verify Reconcile — CP2c-ii: a duplicate-insert 409 (or a reconciled ambiguous failure) is idempotent ONLY if
// the existing event with our deterministic id is LIVE (status != cancelled) AND covers our EXACT slot. A
// race-lost delete leaves the id reserved as a cancelled tombstone → an unverified 409 would falsely report
// "booked". Reconstruct context via node refs; compare times by epoch (Google omits milliseconds).
const be = $('Build Event Request').first().json;
const b = be.booking;
const ev = $json;
const ourStart = new Date(b.startUTC).getTime();
const ourEnd = new Date(b.endUTC).getTime();
const evStart = ev.start && ev.start.dateTime ? new Date(ev.start.dateTime).getTime() : null;
const evEnd = ev.end && ev.end.dateTime ? new Date(ev.end.dateTime).getTime() : null;
const ok = ev.status !== 'cancelled' && evStart === ourStart && evEnd === ourEnd;
return [{ json: { ...be, _reconcile_ok: ok } }];

// Build Reconcile-Handoff State — the deterministic event id exists but as a CANCELLED tombstone (a prior
// booking for this exact slot was deleted, e.g. a CP2b race-loss). We cannot reuse the id and made no new
// booking → hand off. Context rebuilt via node refs (this is an error/branch path — the incoming item is the
// GCal event, not our state).
const be = $('Build Event Request').first().json;
const st = be.state;
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, reconcile_conflict: true } }];
